import{_ as e,o as i,c as t,a6 as o}from"./chunks/framework.Bd7kzaCy.js";const r="/xi-kari-skill/handbook/images/responsibility.svg",u=JSON.parse('{"title":"实际做事的人，为什么不等于全部责任人","description":"先看谁在承接实际工作，再按独立依据判断责任及其范围。","frontmatter":{"title":"实际做事的人，为什么不等于全部责任人","description":"先看谁在承接实际工作，再按独立依据判断责任及其范围。"},"headers":[],"relativePath":"concepts/responsibility.md","filePath":"concepts/responsibility.md"}'),l={name:"concepts/responsibility.md"};function s(n,a,h,c,p,d){return i(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="实际做事的人-为什么不等于全部责任人" tabindex="-1">实际做事的人，为什么不等于全部责任人 <a class="header-anchor" href="#实际做事的人-为什么不等于全部责任人" aria-label="Permalink to &quot;实际做事的人，为什么不等于全部责任人&quot;">​</a></h1><p>谁执行、谁受益、谁能决定、谁应负责，是同一个问题吗？</p><p><strong>先看谁在承接实际工作，再按独立依据判断责任及其范围。</strong></p><h2 id="从具体情景看区别" tabindex="-1">从具体情景看区别 <a class="header-anchor" href="#从具体情景看区别" aria-label="Permalink to &quot;从具体情景看区别&quot;">​</a></h2><p>原文将人员、岗位、程序、设施和技术系统都列为可能的承接载体，因为它们可以实际执行、传导、维护、记录或修复。沿着这组对象看，一台设施可能真的承担了传输功能，一个岗位可能每天完成处理任务，但这些事实还没有回答谁作决定、谁有监督义务、谁应补救。责任主体要另外说明依据、责任类型、知情与控制、范围和期间，不能把最容易看见的执行位置当作全部责任的答案。</p><p>原文同时要求分开成本承担者、受益者和停止权：承接能力强，不会自动产生无限继续承接的义务；解释范围扩大，也不会自动扩大处置权。这样的区分保留实际工作，也让责任判断回到具体关系与规则。</p><figure class="concept-figure"><img src="'+r+'" alt="围绕同一件事，分开五个位置"><figcaption>这些位置可能重合，也可能分开；一项成立不能自动替另一项作结论。</figcaption></figure><h2 id="回到原文" tabindex="-1">回到原文 <a class="header-anchor" href="#回到原文" aria-label="Permalink to &quot;回到原文&quot;">​</a></h2><blockquote><p>低权限执行者不得因最可见而成为默认主要责任人。</p></blockquote><ul><li><a href="/xi-kari-skill/handbook/theory/part-02.html#section-2-8">§2.8 核心词语锁</a></li><li><a href="/xi-kari-skill/handbook/theory/part-07.html#section-7-2-4">§7.2.4 CV（承接载体）</a></li><li><a href="/xi-kari-skill/handbook/theory/part-07.html#section-7-2-5">§7.2.5 RS（责任主体）</a></li></ul><h2 id="这处区别能说明到哪里" tabindex="-1">这处区别能说明到哪里 <a class="header-anchor" href="#这处区别能说明到哪里" aria-label="Permalink to &quot;这处区别能说明到哪里&quot;">​</a></h2><p>承接载体与责任主体是分类区别，分类本身不判定任何具体人的法律或道德责任，也不授权重新分配工作。组织主体资格须依据具体规则判断，不能与设备混为一类。</p><h2 id="接着理解" tabindex="-1">接着理解 <a class="header-anchor" href="#接着理解" aria-label="Permalink to &quot;接着理解&quot;">​</a></h2><ul><li><a href="./recovery.html">依靠支持恢复的功能，算不算真的恢复</a></li><li><a href="./feedback.html">收到消息，为什么还不算有效反馈</a></li><li><a href="./../cases/toyota-andon.html">真实案例 · 丰田安灯：异常怎样进入处理流程</a></li></ul>',14)])])}const m=e(l,[["render",s]]);export{u as __pageData,m as default};
